/**
 * What every primitive of audio/ui shares and the kernel does not do: parts
 * named in kebab case, a value reported as `onValueChange` and
 * `onValueCommitted`, one pointer gesture at a time, and a native input
 * hidden from sight. The primitives import it from `../primitive`.
 */
import {
  bindDrag,
  type ChangeSource,
  createChange,
  definePrimitive as definePrimitiveOf,
  dispatch,
  type PointerSample,
  type PrimitiveContext,
} from "@ui-sdk/core";

/** A boolean as a data attribute: present and empty, or absent. */
export const flag = (on: boolean) => (on ? "" : undefined);

/** What a change reports to `onValueChange`, beside the value. */
export interface ChangeDetails {
  cancel: () => void;
  event?: Event;
  /** The point or segment that moved, for a control that has several. */
  index?: number;
  reason: string;
  source?: string;
}

/** What a commit reports to `onValueCommitted`, beside the value. */
export interface CommitDetails {
  event?: Event;
  index?: number;
  reason: string;
}

/** How a native input is hidden while it keeps the focus, the keys and the name. */
export const VISUALLY_HIDDEN = {
  border: "0",
  "clip-path": "inset(50%)",
  height: "1px",
  margin: "-1px",
  overflow: "hidden",
  padding: "0",
  position: "absolute",
  "white-space": "nowrap",
  width: "1px",
};

/**
 * How a change came about, when its event says. The kernel reads it from
 * input it tracks, so the first interaction would report "programmatic"
 * without this. With no event, the kernel decides, and an agent's change
 * stays the agent's.
 */
export function sourceOf(event?: Event): ChangeSource | undefined {
  if (typeof PointerEvent !== "undefined" && event instanceof PointerEvent) {
    return event.pointerType === "touch" || event.pointerType === "pen"
      ? event.pointerType
      : "mouse";
  }
  if (event instanceof MouseEvent) {
    return "mouse";
  }
  if (event instanceof KeyboardEvent) {
    return "keyboard";
  }
}

/** A change or a commit's details: the reason, the event, and who caused it when the event says. */
function detailsOf(reason: string, event?: Event, extra?: object) {
  const source = sourceOf(event);
  return { event, reason, ...(source ? { source } : {}), ...extra };
}

/**
 * How a primitive whose state holds a `value` reports it: `report` fires
 * `onValueChange` and keeps the value unless an app refused it, `commit`
 * fires `onValueCommitted`, and `setAtOnce` does both, for a change that is
 * over as soon as it is made (a key, a typed value, the wheel, a reset). It
 * skips a value `same` finds equal to the one `displayed` shows; with no
 * `same`, every value is reported, even an unchanged one. `extra` goes into
 * the details, such as the `index` of the point that moved.
 */
export function createReporter<State extends { value: Value }, Value>(
  context: PrimitiveContext<any, State, any>,
  displayed: (state: State) => Value,
  same?: (a: Value, b: Value) => boolean
) {
  const change = createChange(context);
  const state = () => context.store.get() as State;
  const commit = (
    value: Value,
    reason: string,
    event?: Event,
    extra?: object
  ) => {
    dispatch(
      context,
      "onValueCommitted",
      value,
      detailsOf(reason, event, extra)
    );
  };
  const report = (
    value: Value,
    reason: string,
    event?: Event,
    extra?: object
  ) =>
    change("value", value as never, detailsOf(reason, event, extra) as never);
  const setAtOnce = (
    value: Value,
    reason: string,
    event?: Event,
    extra?: object
  ) => {
    if (same?.(value, displayed(state()))) {
      return;
    }
    if (report(value, reason, event, extra)) {
      commit(value, reason, event, extra);
    }
  };
  return { commit, report, setAtOnce, state };
}

/** Two numbers as one text: a comma between them, or a semicolon where the comma is the decimal mark. */
export function formatPair(formatter: Intl.NumberFormat, a: number, b: number) {
  const decimalComma = formatter
    .formatToParts(1.5)
    .some((part) => part.type === "decimal" && part.value === ",");
  return `${formatter.format(a)}${decimalComma ? "; " : ", "}${formatter.format(b)}`;
}

/** Where in an interval a curve is checked against its chord, how many times an interval may be halved, and a ceiling on the vertices of one curve. */
const PROBES = [0.25, 0.5, 0.75];
const MAX_DEPTH = 8;
const MAX_SAMPLES = 4096;

/**
 * The vertices of a polyline that draws `f(t)` for `t` from 0 to 1 without
 * straying more than `tolerance` from it: it starts from `grid` and halves
 * every interval whose curve leaves its chord. `width` is how wide `t` from 0
 * to 1 spans in the box the curve is drawn in.
 */
export function adaptiveSamples(
  f: (t: number) => number,
  grid: readonly number[],
  tolerance: number,
  width = 1
) {
  const samples: [number, number][] = [];
  let budget = MAX_SAMPLES - grid.length;
  const refine = (
    from: number,
    start: number,
    to: number,
    end: number,
    depth: number
  ) => {
    if (depth >= MAX_DEPTH || budget <= 0) {
      return;
    }
    let stray = 0;
    let middle = Number.NaN;
    for (const probe of PROBES) {
      const value = f(from + (to - from) * probe);
      stray = Math.max(
        stray,
        Math.abs(value - (start + (end - start) * probe))
      );
      if (probe === 0.5) {
        middle = value;
      }
    }
    const slope = (end - start) / ((to - from) * width);
    if (stray / Math.sqrt(1 + slope * slope) <= tolerance) {
      return;
    }
    const half = (from + to) / 2;
    budget -= 1;
    refine(from, start, half, middle, depth + 1);
    samples.push([half, middle]);
    refine(half, middle, to, end, depth + 1);
  };
  const values = grid.map(f);
  grid.forEach((t, index) => {
    const value = values[index] ?? 0;
    samples.push([t, value]);
    const next = grid[index + 1];
    if (next !== undefined) {
      refine(t, value, next, values[index + 1] ?? 0, 0);
    }
  });
  return samples;
}

/**
 * What a change reports: why it happened (`reason`), the event behind it,
 * and `cancel()` to refuse the change.
 */
export interface ChangeEventDetails<Reason extends string, E extends Event> {
  cancel: () => void;
  event: E;
  readonly isCanceled: boolean;
  reason: Reason;
}

/** What a commit reports once a gesture ends: why it happened and the event behind it. */
export interface CommitEventDetails<Reason extends string, E extends Event> {
  event: E;
  reason: Reason;
}

/** The details of a change for `reason` and `event`, with `cancel()` to refuse it. */
export function createChangeEventDetails<
  Reason extends string,
  E extends Event,
>(reason: Reason, event: E): ChangeEventDetails<Reason, E> {
  let canceled = false;
  return {
    cancel: () => {
      canceled = true;
    },
    event,
    get isCanceled() {
      return canceled;
    },
    reason,
  };
}

/**
 * One pointer at a time on a control: while one drags, a press from another is
 * ignored, and the same pointer pressing again means its release was missed,
 * so the drag it left ends there. Moves arrive at most once per frame, each
 * with where the pointer was at the last one.
 */
export function createPointerLock() {
  type Held = {
    end: (event: PointerEvent) => void;
    pointerId: number;
    stop: () => void;
  };
  let held: Held | null = null;
  return {
    claim: (event: PointerEvent) => {
      if (!held) {
        return true;
      }
      if (held.pointerId !== event.pointerId) {
        return false;
      }
      const stale = held;
      held = null;
      stale.stop();
      stale.end(event);
      return true;
    },
    follow: (
      target: Element,
      down: PointerEvent,
      move: (event: PointerEvent, from: { x: number; y: number }) => void,
      end: (event: PointerEvent) => void
    ) => {
      let last = { x: down.clientX, y: down.clientY };
      const entry: Held = {
        end,
        pointerId: down.pointerId,
        stop: () => undefined,
      };
      held = entry;
      entry.stop = bindDrag(target as HTMLElement, down, {
        onEnd: (event) => {
          if (held === entry) {
            held = null;
          }
          end(event);
        },
        onMove: ({ event }) => {
          const from = last;
          last = { x: event.clientX, y: event.clientY };
          move(event, from);
        },
      });
    },
  };
}

/**
 * A value that changes outside the framework, in the shape of an external
 * store: `subscribe` registers a listener called on each change, and
 * `getSnapshot` returns the current value. What a primitive's `source` reads
 * from, so that following a signal costs no render.
 */
export interface Source<Value> {
  getSnapshot: () => Value;
  subscribe: (listener: () => void) => () => void;
}

/** A source that also takes values: what `createSource` returns. */
export interface WritableSource<Value> extends Source<Value> {
  /** Publishes a value. Subscribers are told every time, so the same array, updated in place, can be published again. */
  set: (value: Value) => void;
}

/**
 * A source you push to yourself, from an audio callback, a WebSocket, a worker
 * or a test: call `set` with each new reading, and whatever reads the source
 * follows.
 */
export function createSource<Value>(initial: Value): WritableSource<Value> {
  let value = initial;
  const listeners = new Set<() => void>();
  return {
    getSnapshot: () => value,
    set: (next) => {
      value = next;
      for (const listener of listeners) {
        listener();
      }
    },
    subscribe: (listener) => {
      listeners.add(listener);
      return () => {
        listeners.delete(listener);
      };
    },
  };
}

/** A value the primitive holds and its parts read outside any render. */
export interface Store<Value> {
  get: () => Value;
  set: (next: Value) => void;
  subscribe: (listener: () => void) => () => void;
}

/** A store holding `initial`: `set` tells every listener, unless the value is the same one. */
export function createStore<Value>(initial: Value): Store<Value> {
  let value = initial;
  const listeners = new Set<() => void>();
  return {
    get: () => value,
    set: (next) => {
      if (Object.is(next, value)) {
        return;
      }
      value = next;
      for (const listener of listeners) {
        listener();
      }
    },
    subscribe: (listener) => {
      listeners.add(listener);
      return () => listeners.delete(listener);
    },
  };
}

/** What a gesture hears, from the press that started it to its release. */
export interface GestureHandlers<Data> {
  /** The pointer lifted, or the browser took it over (`canceled`). */
  onEnd: (event: PointerEvent, data: Data, canceled: boolean) => void;
  /** At most once per frame, with the latest pointer event. */
  onMove: (event: PointerEvent, data: Data, sample: PointerSample) => void;
}

/**
 * A primitive's pointer gestures, one at a time. Call `accepts` first, before
 * the primitive's own guards: another pointer pressing while a gesture runs
 * is refused, so a second finger does not take the gesture over, and the
 * same pointer pressing again means its release was missed, so its gesture
 * ends there, through `onStale`. A gesture carries `data` of its own, read
 * back by `active`, and stops when the primitive is destroyed.
 */
export function createGestures<Data>(context: {
  onDestroy: (cleanup: () => void) => void;
}) {
  type Running = { data: Data; pointerId: number; stop: () => void };
  let running: Running | null = null;
  context.onDestroy(() => running?.stop());
  return {
    /** Whether `event` may start a gesture, ending a stale one of the same pointer first. */
    accepts(event: PointerEvent, onStale?: (data: Data) => void) {
      const stale = running;
      if (!stale) {
        return true;
      }
      if (stale.pointerId !== event.pointerId) {
        return false;
      }
      running = null;
      stale.stop();
      onStale?.(stale.data);
      return true;
    },
    /** The data of the gesture that runs, if any. */
    active: () => running?.data ?? null,
    /** Follows the press on `el` until it lifts. */
    start(
      el: HTMLElement,
      event: PointerEvent,
      data: Data,
      handlers: GestureHandlers<Data>
    ) {
      running?.stop();
      const entry: Running = {
        data,
        pointerId: event.pointerId,
        stop: () => undefined,
      };
      running = entry;
      entry.stop = bindDrag(el, event, {
        onEnd: (end, canceled) => {
          if (running === entry) {
            running = null;
          }
          handlers.onEnd(end, data, canceled);
        },
        onMove: (sample) => handlers.onMove(sample.event, data, sample),
      });
    },
  };
}

/** An element's box for one gesture, from `measuredBox`. */
export interface MeasuredBox {
  /** The box: measured the first time, and again only after the page scrolled or resized. */
  get: () => DOMRect;
  /** Stops watching the page. Call it when the gesture ends. */
  stop: () => void;
}

/**
 * An element's box, measured once for a gesture rather than on each of its
 * moves. Read after a move wrote to the page, `getBoundingClientRect` makes
 * the browser lay the page out on the spot, every frame. A scroll or a resize
 * during the gesture moves the element, so either one measures it again.
 */
export function measuredBox(element: Element): MeasuredBox {
  let box: DOMRect | null = null;
  const view = element.ownerDocument?.defaultView;
  const stale = () => {
    box = null;
  };
  view?.addEventListener("scroll", stale, { capture: true, passive: true });
  view?.addEventListener("resize", stale, { passive: true });
  return {
    get: () => {
      box ??= element.getBoundingClientRect();
      return box;
    },
    stop: () => {
      view?.removeEventListener("scroll", stale, { capture: true });
      view?.removeEventListener("resize", stale);
    },
  };
}

const KEBAB = /([a-z0-9])([A-Z])/g;
const kebab = (name: string) => name.replace(KEBAB, "$1-$2").toLowerCase();

/**
 * The part a primitive draws names itself in `data-slot`, in kebab case
 * (`xypad-input-x`, `piano-roll-note`), the names the styles and the docs
 * select: the kernel writes the slot's key as it is (`xypad-inputX`). A
 * component that gives its own name to a part (`timeline-time-selection`)
 * keeps it.
 */
function nameSlots(name: string, slots: Record<string, any>) {
  const prefix = kebab(name);
  for (const [key, definition] of Object.entries(slots)) {
    const fallback = key === "root" ? prefix : `${prefix}-${kebab(key)}`;
    const { attrs } = definition;
    definition.attrs = (state: unknown, context: { props?: object }) => ({
      ...attrs?.(state, context),
      "data-slot":
        (context.props as Record<string, string> | undefined)?.["data-slot"] ??
        fallback,
    });
    definition.props = { ...definition.props, "data-slot": "string" };
  }
  return slots;
}

/** `definePrimitive` of the kernel, with the parts named in kebab case and a `data-slot` that can be given. */
export const definePrimitive = ((options: any) =>
  definePrimitiveOf({
    ...options,
    slots: (slot: unknown) => nameSlots(options.name, options.slots(slot)),
  })) as typeof definePrimitiveOf;

/** The number a typed text means: "-6", "-6 dB" or "12,5". */
const typedNumber = (text: string) => {
  const parsed = Number.parseFloat(text.trim().replace(",", "."));
  return Number.isFinite(parsed) ? parsed : null;
};

const INPUT_STYLE =
  "position: absolute; inset: 0; width: 100%; height: 100%; margin: 0; padding: 0; border: 0; border-radius: inherit; background: inherit; color: inherit; font: inherit; text-align: center; box-sizing: border-box";

/**
 * Lets the reader type a value into a control's readout: a double click on
 * it, or Enter or F2 while it has focus, lays a text field over it. Enter or
 * leaving the field gives the control the number typed, through its native
 * range input, as a drag would; Escape keeps the value. The framework keeps
 * drawing the readout's text under the field. `root` is the control's slot
 * (`knob`, `fader`). Returns what takes it away.
 */
export function editableReadout(readout: HTMLElement, root: string) {
  let field: HTMLInputElement | null = null;
  const positioned = readout.style.position;
  const finish = (text: string | null) => {
    if (!field) {
      return;
    }
    field.remove();
    field = null;
    readout.removeAttribute("data-editing");
    readout.style.position = positioned;
    readout.focus({ preventScroll: true });
    const typed = text === null ? null : typedNumber(text);
    const input = readout
      .closest(`[data-slot="${root}"]`)
      ?.querySelector<HTMLInputElement>('input[type="range"]');
    if (typed === null || !input) {
      return;
    }
    Object.getOwnPropertyDescriptor(
      HTMLInputElement.prototype,
      "value"
    )?.set?.call(input, String(typed));
    input.dispatchEvent(new Event("input", { bubbles: true }));
    input.dispatchEvent(new Event("change", { bubbles: true }));
  };
  const open = () => {
    if (field || readout.closest("[data-disabled]")) {
      return;
    }
    const text = readout.textContent?.trim() ?? "";
    field = document.createElement("input");
    field.type = "text";
    field.inputMode = "decimal";
    field.value = text;
    field.size = Math.max(text.length, 3);
    field.style.cssText = INPUT_STYLE;
    const label = readout.getAttribute("aria-label");
    if (label) {
      field.setAttribute("aria-label", label);
    }
    field.addEventListener("keydown", (event) => {
      event.stopPropagation();
      if (event.key === "Enter") {
        event.preventDefault();
        finish(field?.value ?? null);
      } else if (event.key === "Escape") {
        event.preventDefault();
        finish(null);
      }
    });
    field.addEventListener("blur", () => finish(field?.value ?? null));
    if (getComputedStyle(readout).position === "static") {
      readout.style.position = "relative";
    }
    readout.setAttribute("data-editing", "");
    readout.appendChild(field);
    field.focus({ preventScroll: true });
    field.select();
  };
  // A readout inside a thumb or a control must not also reset or drag it.
  const handleDoubleClick = (event: MouseEvent) => {
    event.stopPropagation();
    open();
  };
  const handleKeyDown = (event: KeyboardEvent) => {
    if (
      event.target === readout &&
      (event.key === "Enter" || event.key === "F2")
    ) {
      event.preventDefault();
      open();
    }
  };
  const handlePointerDown = (event: PointerEvent) => event.stopPropagation();
  const tabIndex = readout.getAttribute("tabindex");
  readout.tabIndex = 0;
  readout.setAttribute("aria-keyshortcuts", "Enter");
  readout.setAttribute("data-editable", "");
  readout.addEventListener("dblclick", handleDoubleClick);
  readout.addEventListener("keydown", handleKeyDown);
  readout.addEventListener("pointerdown", handlePointerDown);
  return () => {
    finish(null);
    readout.removeEventListener("dblclick", handleDoubleClick);
    readout.removeEventListener("keydown", handleKeyDown);
    readout.removeEventListener("pointerdown", handlePointerDown);
    readout.removeAttribute("aria-keyshortcuts");
    readout.removeAttribute("data-editable");
    if (tabIndex === null) {
      readout.removeAttribute("tabindex");
    } else {
      readout.setAttribute("tabindex", tabIndex);
    }
  };
}

import {
  css,
  type PrimitiveInstance,
  type PropSpec,
  type SlotDefinition,
} from "@ui-sdk/core";
import { numberFormatter } from "@ui-sdk/core/number";
import { definePrimitive, flag } from "../primitive";
import { type LevelScale, levelPosition, type MeterFrame } from "./levels";

export type { LevelScale, LevelScaleFunction, MeterFrame } from "./levels";

/**
 * The meter. Levels arrive two ways: as `value` (and `peak`), arrays the app
 * renders, which the server writes too; or from a live `source` an engine
 * pushes to every frame. A source is painted straight onto the elements of
 * each channel, from one subscription for all the channels, so a signal
 * updating 60 times a second never renders the framework.
 *
 * A channel is keyed by its `index`, as the kernel keys the items of a
 * collection: the indicator, the peak, the value and the label inside it take
 * the index from it.
 */

/** Which way a meter's bars run. */
export type MeterOrientation = "horizontal" | "vertical";

/** A live frame an engine pushes to: what it holds now, and a way to hear it change. */
export interface MeterSource {
  getSnapshot: () => MeterFrame;
  subscribe: (listener: () => void) => () => void;
}

/** Levels read to one decimal: finer than a meter can be read, and a plain number rather than a share of the range. */
const DEFAULT_FORMAT: Intl.NumberFormatOptions = { maximumFractionDigits: 1 };

export interface MeterPrimitiveOptions {
  /** Level at or above which a channel is clipping. @default 0 */
  clipThreshold?: number;
  format?: Intl.NumberFormatOptions;
  locale?: Intl.LocalesArgument;
  /** @default 6 */
  max?: number;
  /** @default -60 */
  min?: number;
  /** @default "vertical" */
  orientation?: MeterOrientation;
  /** Peak-hold level per channel. */
  peak?: readonly number[];
  /** How levels are spread along the length. @default "linear" */
  scale?: LevelScale;
  /** A live frame an engine pushes to, painted without a render. */
  source?: MeterSource;
  /** Level per channel; the array length is the channel count. */
  value?: readonly number[];
  /** Level at or above which a channel is in its warning zone. Unset, there is none. */
  warnThreshold?: number;
}

/** The range, the warning and clipping levels, the position of a level along the meter, and how a level is written. */
export interface MeterConfig {
  clipThreshold: number;
  formatter: Intl.NumberFormat;
  max: number;
  min: number;
  /** A level's position along the length, 0 to 1. */
  position: (level: number) => number;
  warnThreshold: number;
}

export interface MeterState {
  channelCount: number;
  config: MeterConfig;
  /** The frame the parts render, before any live one: the app's, or the source's current. */
  frame: MeterFrame;
  /** The channels that have a label part, by index. */
  labelled: readonly number[];
  orientation: MeterOrientation;
  source: MeterSource | undefined;
}

function configOf(options: MeterPrimitiveOptions): MeterConfig {
  const min = options.min ?? -60;
  const max = options.max ?? 6;
  return {
    clipThreshold: options.clipThreshold ?? 0,
    formatter: numberFormatter(
      options.locale as string | undefined,
      options.format ?? DEFAULT_FORMAT
    ),
    max,
    min,
    position: levelPosition(options.scale ?? "linear", min, max),
    warnThreshold: options.warnThreshold ?? Number.POSITIVE_INFINITY,
  };
}

const frameOf = (options: MeterPrimitiveOptions): MeterFrame =>
  options.source
    ? options.source.getSnapshot()
    : { levels: options.value ?? [], peaks: options.peak };

function stateOf(options: MeterPrimitiveOptions): MeterState {
  const frame = frameOf(options);
  return {
    channelCount: frame.levels.length,
    config: configOf(options),
    frame,
    labelled: [],
    orientation: options.orientation ?? "vertical",
    source: options.source,
  };
}

/** What one channel shows for a level. */
export interface MeterChannelView {
  clipping: boolean;
  /** Peak mark position, 0 to 1; undefined when there is no peak for the channel. */
  peakPercent: number | undefined;
  /** Indicator length, 0 to 1. */
  percent: number;
  text: string;
  valueNow: number;
  /** At or above the warning level, and not yet clipping. */
  warning: boolean;
}

/** What channel `index` shows for its reading in `frame`, the state's own unless given: its bar, its peak mark, whether it warns or clips, its text. */
export function channelView(
  state: MeterState,
  index: number,
  frame: MeterFrame = state.frame
): MeterChannelView {
  const { clipThreshold, formatter, min, position, warnThreshold } =
    state.config;
  const level = frame.levels[index] ?? min;
  const peak = frame.peaks?.[index];
  // One decimal keeps a live signal from rewriting the attribute every frame.
  const valueNow = Math.round(level * 10) / 10;
  return {
    clipping: level >= clipThreshold,
    peakPercent: peak === undefined ? undefined : position(peak),
    percent: position(level),
    text: formatter.format(valueNow),
    valueNow,
    warning: level >= warnThreshold && level < clipThreshold,
  };
}

/** The DOM nodes of one channel that a live source writes to. */
interface ChannelNodes {
  channel?: HTMLElement;
  getAriaValueText?: (
    formattedValue: string,
    value: number,
    index: number
  ) => string;
  indicator?: HTMLElement;
  peak?: HTMLElement;
  value?: HTMLElement;
}

/** Sets `attribute` on `node` as an empty attribute, or removes it. */
function setPresence(node: Element, attribute: string, present: boolean) {
  if (present) {
    node.setAttribute(attribute, "");
  } else {
    node.removeAttribute(attribute);
  }
}

/** Writes the level's text into the value part's first text node, which the framework made. */
function writeText(part: HTMLElement, text: string) {
  for (const child of part.childNodes) {
    if (child.nodeType === Node.TEXT_NODE) {
      if (child.nodeValue !== text) {
        child.nodeValue = text;
      }
      return;
    }
  }
  part.appendChild(document.createTextNode(text));
}

/** Writes one channel's view straight to its nodes, touching only what changed. */
function paintChannel(
  nodes: ChannelNodes,
  view: MeterChannelView,
  index: number,
  orientation: MeterOrientation
) {
  const { channel, indicator, peak, value } = nodes;
  if (indicator) {
    indicator.style.transform =
      orientation === "horizontal"
        ? `scaleX(${view.percent})`
        : `scaleY(${view.percent})`;
    setPresence(indicator, "data-clipping", view.clipping);
    setPresence(indicator, "data-warning", view.warning);
    // Latched: it stays until a click on the meter clears it.
    if (view.clipping) {
      setPresence(indicator, "data-clipped", true);
    }
  }
  if (peak) {
    peak.hidden = view.peakPercent === undefined;
    if (view.peakPercent !== undefined) {
      peak.style[orientation === "horizontal" ? "left" : "bottom"] =
        `${view.peakPercent * 100}%`;
    }
  }
  if (channel) {
    const valueNow = String(view.valueNow);
    if (channel.getAttribute("aria-valuenow") !== valueNow) {
      channel.setAttribute("aria-valuenow", valueNow);
      channel.setAttribute(
        "aria-valuetext",
        nodes.getAriaValueText?.(view.text, view.valueNow, index) ?? view.text
      );
    }
    setPresence(channel, "data-clipping", view.clipping);
    setPresence(channel, "data-warning", view.warning);
    if (view.clipping) {
      setPresence(channel, "data-clipped", true);
    }
  }
  if (value) {
    writeText(value, view.text);
  }
}

const SLOT = (name: string) => `[data-slot="meter-${name}"]`;

/**
 * Finds the parts of a channel a live source writes to. A framework that binds
 * a parent before its children, as custom elements do, has not marked them
 * yet when the channel binds, so what is missing is looked for again.
 */
function resolve(nodes: ChannelNodes) {
  const { channel } = nodes;
  if (channel) {
    nodes.indicator ??=
      channel.querySelector<HTMLElement>(SLOT("indicator")) ?? undefined;
    nodes.peak ??=
      channel.querySelector<HTMLElement>(SLOT("peak")) ?? undefined;
    nodes.value ??=
      channel.querySelector<HTMLElement>(SLOT("value")) ?? undefined;
  }
  return nodes;
}

/** What a part's className, style and children functions read of the meter. */
export interface MeterPublicState {
  channelCount: number;
  orientation: MeterOrientation;
}

/** What a channel and the parts inside it read of their channel. */
export interface ChannelPublicState {
  /** Whether the level is at or above the clip threshold. */
  clipping: boolean;
  index: number;
  orientation: MeterOrientation;
  /** The level as text, with `format` and `locale`. */
  text: string;
  /** The level, to one decimal. */
  valueNow: number;
  /** Whether the level is at or above the warning level, below the clip threshold. */
  warning: boolean;
}

/** The channel's view as the state its parts read. */
function channelState(state: MeterState, index: number): ChannelPublicState {
  const view = channelView(state, index);
  return {
    clipping: view.clipping,
    index,
    orientation: state.orientation,
    text: view.text,
    valueNow: view.valueNow,
    warning: view.warning,
  };
}

/** The attributes every part of a channel carries. */
const channelAttrs = (channel: ChannelPublicState) => ({
  "data-clipping": flag(channel.clipping),
  "data-orientation": channel.orientation,
  "data-warning": flag(channel.warning),
});

/** What a meter's `api` gives an adapter. */
export interface MeterApi {
  /** The nodes of each channel a live source is painted onto. */
  channels: Map<number, ChannelNodes>;
  /** Which key a `"key"` prop is keyed by. */
  internal: { keyOf: (index: unknown) => string };
}

/** The props every part takes. */
interface PartProps {
  id?: string;
}

/** The props of a part inside a channel: the channel's index, which it inherits. */
interface InChannel extends PartProps {
  index?: number;
  /** The same index, inherited too: what the kernel tells the parts of two channels apart by. */
  value?: number;
}

/** The meter's slots, by name, with the props and the public state of each. */
export type MeterSlots = {
  channel: SlotDefinition<
    MeterState,
    MeterApi,
    PartProps & {
      getAriaValueText?: (
        formatted: string,
        value: number,
        index: number
      ) => string;
      index: number;
    },
    ChannelPublicState
  >;
  indicator: SlotDefinition<
    MeterState,
    MeterApi,
    InChannel,
    ChannelPublicState
  >;
  label: SlotDefinition<MeterState, MeterApi, InChannel, object>;
  mark: SlotDefinition<
    MeterState,
    MeterApi,
    PartProps & { value: number },
    MeterPublicState
  >;
  peak: SlotDefinition<MeterState, MeterApi, InChannel, ChannelPublicState>;
  root: SlotDefinition<MeterState, MeterApi, PartProps, MeterPublicState>;
  track: SlotDefinition<MeterState, MeterApi, PartProps, object>;
  value: SlotDefinition<MeterState, MeterApi, InChannel, ChannelPublicState>;
};

/**
 * The type of `meter`, written out: the kernel's own types its inferred type
 * would name are not exported, so a declaration could not print it.
 */
export interface MeterPrimitive {
  options: Record<string, PropSpec> | undefined;
  slots: MeterSlots;
  (
    initialOptions: MeterPrimitiveOptions & { id: string }
  ): Omit<PrimitiveInstance, "api" | "get" | "types"> & {
    api: MeterApi;
    get: () => MeterState;
    types: {
      api: MeterApi;
      options: MeterPrimitiveOptions;
      slots: MeterSlots;
      state: MeterState;
    };
  };
}

/**
 * What a part inside a channel takes from it: its index, and the same index
 * as `value`, which the kernel keys a part by, so the labels (and the other
 * parts) of two channels are two parts and not one.
 */
const IN_CHANNEL = {
  index: { from: "channel", kind: "number", required: true },
  value: { from: "channel.index", kind: "number" },
} as const;

/** The index of a part inside a channel, which it inherits as the key's text. */
const indexOf = (props: InChannel) => Number(props.index ?? 0);

const noop = () => undefined;

export const meter: MeterPrimitive = definePrimitive({
  api: () => ({
    channels: new Map<number, ChannelNodes>(),
    internal: { keyOf: (index: unknown) => String(index) },
  }),
  name: "meter",
  options: {
    clipThreshold: "number",
    format: "value",
    locale: "value",
    max: "number",
    min: "number",
    orientation: "string",
    peak: "value",
    scale: "value",
    source: "value",
    value: "value",
    warnThreshold: "number",
  },
  slots: (slot) => ({
    channel: slot<
      {
        getAriaValueText?: (
          formatted: string,
          value: number,
          index: number
        ) => string;
        index: number;
      },
      ChannelPublicState
    >({
      attrs: (state: MeterState, { id, props }) => {
        // An index written as an attribute comes as text.
        const index = Number(props.index);
        const view = channelView(state, index);
        const { max, min } = state.config;
        return {
          ...channelAttrs(channelState(state, index)),
          "aria-labelledby": state.labelled.includes(index)
            ? `${id}-label-${index}`
            : undefined,
          "aria-valuemax": String(max),
          "aria-valuemin": String(min),
          "aria-valuenow": String(Math.min(max, Math.max(min, view.valueNow))),
          "aria-valuetext":
            props.getAriaValueText?.(view.text, view.valueNow, index) ??
            view.text,
          role: "meter",
          style: css({ position: "relative" }),
        };
      },
      // A live source paints the channel's elements itself, from the root's one subscription.
      bind: (el, part) => {
        const index = Number(part.props.index);
        const nodes: ChannelNodes = {
          channel: el,
          getAriaValueText: part.props.getAriaValueText,
        };
        part.api.channels.set(index, nodes);
        const state = part.store.get();
        if (state.source) {
          const view = channelView(state, index, state.source.getSnapshot());
          paintChannel(resolve(nodes), view, index, state.orientation);
        }
        return () => part.api.channels.delete(index);
      },
      // A formatter, read for its result: "callback" would make it an event in Vue.
      props: { getAriaValueText: "value", index: "key" },
      state: (state: MeterState, { props }) =>
        channelState(state, Number(props.index)),
    }),
    indicator: slot<InChannel, ChannelPublicState>({
      attrs: (state: MeterState, { props }) => {
        const index = indexOf(props);
        const { percent } = channelView(state, index);
        const horizontal = state.orientation === "horizontal";
        return {
          ...channelAttrs(channelState(state, index)),
          "aria-hidden": "true",
          style: css({
            height: "100%",
            "inset-inline-start": "0",
            transform: horizontal ? `scaleX(${percent})` : `scaleY(${percent})`,
            "transform-origin": horizontal ? "left center" : "center bottom",
            width: "100%",
            "will-change": "transform",
          }),
        };
      },
      props: IN_CHANNEL,
      state: (state: MeterState, { props }) =>
        channelState(state, indexOf(props)),
    }),
    label: slot<InChannel>({
      attrs: (_state: MeterState, { id, props }) => ({
        id: `${id}-label-${indexOf(props)}`,
        role: "presentation",
      }),
      bind: (_el, part) => {
        const index = indexOf(part.props);
        part.store.set({ labelled: [...part.store.get().labelled, index] });
        return () =>
          part.store.set({
            labelled: part.store
              .get()
              .labelled.filter((each) => each !== index),
          });
      },
      props: IN_CHANNEL,
    }),
    mark: slot<{ value: number }, MeterPublicState>({
      attrs: (state: MeterState, { props }) => {
        const at = state.config.position(props.value) * 100;
        return {
          "aria-hidden": "true",
          "data-orientation": state.orientation,
          style: css({
            position: "absolute",
            ...(state.orientation === "vertical"
              ? { bottom: `${at}%` }
              : { "inset-inline-start": `${at}%` }),
          }),
        };
      },
      props: { value: "number" },
      state: (state: MeterState) => ({
        channelCount: state.channelCount,
        orientation: state.orientation,
      }),
    }),
    peak: slot<InChannel, ChannelPublicState>({
      attrs: (state: MeterState, { props }) => {
        const index = indexOf(props);
        const { peakPercent } = channelView(state, index);
        const at = `${(peakPercent ?? 0) * 100}%`;
        return {
          ...channelAttrs(channelState(state, index)),
          "aria-hidden": "true",
          hidden: peakPercent === undefined ? "" : undefined,
          style: css(
            state.orientation === "horizontal" ? { left: at } : { bottom: at }
          ),
        };
      },
      props: IN_CHANNEL,
      state: (state: MeterState, { props }) =>
        channelState(state, indexOf(props)),
    }),
    root: slot<object, MeterPublicState>({
      attrs: (state: MeterState) => ({
        "data-orientation": state.orientation,
        role: "group",
      }),
      // One subscription paints every channel of a live source.
      bind: (_el, part) => {
        let watched: MeterSource | undefined;
        let stop: () => void = noop;
        const paint = () => {
          const state = part.store.get();
          if (!state.source) {
            return;
          }
          const frame = state.source.getSnapshot();
          if (frame.levels.length !== state.channelCount) {
            part.store.set({ channelCount: frame.levels.length });
          }
          for (const [index, nodes] of part.api.channels) {
            if (index < frame.levels.length) {
              paintChannel(
                resolve(nodes),
                channelView(state, index, frame),
                index,
                state.orientation
              );
            }
          }
        };
        const watch = () => {
          const { source } = part.store.get();
          if (source !== watched) {
            stop();
            watched = source;
            stop = source ? source.subscribe(paint) : noop;
          }
          paint();
        };
        watch();
        const off = part.store.subscribe(watch);
        return () => {
          off();
          stop();
        };
      },
      on: {
        // A click anywhere on the meter clears what a live source latched, as in a DAW.
        click: (_event, { el }) => {
          for (const node of el?.querySelectorAll("[data-clipped]") ?? []) {
            setPresence(node, "data-clipped", false);
          }
        },
      },
      state: (state: MeterState) => ({
        channelCount: state.channelCount,
        orientation: state.orientation,
      }),
    }),
    track: slot({ attrs: () => ({}) }),
    value: slot<InChannel, ChannelPublicState>({
      attrs: () => ({ "aria-hidden": "true" }),
      props: IN_CHANNEL,
      state: (state: MeterState, { props }) =>
        channelState(state, indexOf(props)),
    }),
  }),
  state: stateOf,
  // What the options give, not what the parts registered: the labels stay.
  sync: (options: MeterPrimitiveOptions) => {
    const { labelled: _labelled, ...held } = stateOf(options);
    return held;
  },
});

/**
 * How a level in dB is placed along a meter, and what one reading of the meter
 * is: shared by the meter and by what draws a needle or a level history.
 */

/** One reading of the meter: a level per channel, and optionally a peak-hold level per channel. */
export interface MeterFrame {
  levels: readonly number[];
  peaks?: readonly number[] | undefined;
}

/**
 * How a level in dB is spread along the meter's length: evenly, or the way
 * digital peak meters spread it, with room at the top where it matters.
 */
export type LevelScale = "iec" | "linear" | LevelScaleFunction;

/** A custom curve: any increasing function of the level, rescaled to the meter's range. */
export type LevelScaleFunction = (level: number) => number;

/**
 * The deflection of an IEC 60268-18 style digital peak meter, from 0 at
 * -70 dB to 100 at 0 dB: each stretch of the scale gets more room than the
 * one below, so the top 20 dB take half the length.
 */
export function iecDeflection(level: number): number {
  if (level < -70) {
    return 0;
  }
  if (level < -60) {
    return (level + 70) * 0.25;
  }
  if (level < -50) {
    return (level + 60) * 0.5 + 2.5;
  }
  if (level < -40) {
    return (level + 50) * 0.75 + 7.5;
  }
  if (level < -30) {
    return (level + 40) * 1.5 + 15;
  }
  if (level < -20) {
    return (level + 30) * 2 + 30;
  }
  return (level + 20) * 2.5 + 50;
}

/**
 * The deflection of a VU meter's pointer. It moves with the voltage of the
 * signal, not with its dB, so on a scale that ends at +3 VU the mark of 0 VU
 * sits at 71% of the length and that of -20 VU at 7%. Give it to
 * `levelPosition` from `Number.NEGATIVE_INFINITY`, where the pointer rests.
 */
export function vuDeflection(level: number): number {
  return 10 ** (level / 20);
}

const evenly: LevelScaleFunction = (level) => level;

/** A function from a level to its position along the length, 0 at `min` and 1 at `max`. */
export function levelPosition(
  scale: LevelScale,
  min: number,
  max: number
): (level: number) => number {
  let curve = scale;
  if (scale === "iec") {
    curve = iecDeflection;
  } else if (scale === "linear") {
    curve = evenly;
  }
  const spread = curve as LevelScaleFunction;
  const low = spread(min);
  const span = spread(max) - low || 1;
  return (level) => Math.min(1, Math.max(0, (spread(level) - low) / span));
}

import { createParts } from "@ui-sdk/web";
import { channelView, type MeterState, meter } from "./core";

/** Writes the level's text as one text node's data, so a change restyles nothing else. */
function writeText(part: Element, text: string) {
  const node =
    part.firstChild instanceof Text
      ? part.firstChild
      : part.appendChild(document.createTextNode(""));
  if (node.data !== text) {
    node.data = text;
  }
}

/**
 * What React renders as children, the meter draws here: each value part's
 * text, from the levels it holds. A live source writes the text itself, frame
 * by frame. The meter connects before its parts are parsed, so it draws again
 * once they bind.
 */
function drawValues(
  el: HTMLElement,
  instance: {
    get: () => object;
    subscribe: (listener: () => void) => () => void;
  }
) {
  const draw = () => {
    const state = instance.get() as MeterState;
    for (const channel of el.querySelectorAll("audio-ui-meter-channel")) {
      const index = Number(channel.getAttribute("index"));
      const value = channel.querySelector("audio-ui-meter-value");
      if (value) {
        writeText(value, channelView(state, index).text);
      }
    }
  };
  draw();
  queueMicrotask(draw);
  return instance.subscribe(draw);
}

const jsonAttribute = (value: string | null) =>
  value ? JSON.parse(value) : undefined;

/** The whole web adapter of the meter: a tag for each part, and how attributes read. */
export const parts = createParts(meter, {
  channel: { display: "block", tag: "audio-ui-meter-channel" },
  indicator: { display: "block", tag: "audio-ui-meter-indicator" },
  label: "audio-ui-meter-label",
  mark: "audio-ui-meter-mark",
  peak: { display: "block", tag: "audio-ui-meter-peak" },
  root: {
    display: "block",
    kinds: {
      format: jsonAttribute,
      locale: "string",
      orientation: "string",
      peak: jsonAttribute,
      scale: (value) => value ?? undefined,
      value: jsonAttribute,
    },
    render: drawValues,
    tag: "audio-ui-meter",
  },
  track: { display: "block", tag: "audio-ui-meter-track" },
  value: "audio-ui-meter-value",
});
